// slmm-comm-capture.mjs
// ---------------------------------------------------------------------------
// Pure helpers for the Client Communication harness. No network I/O.
//
// T10 fix: the office-reply support_message id is NOT read from the POST
// response (representations are not guaranteed). It is resolved by a
// deterministic lookup scoped strictly to THIS run's scratch thread plus the
// unique body generated by this run. The id may only enter the current-run
// cleanup allowlist after resolveOfficeReplyId() has confirmed a UNIQUE match;
// otherwise the harness FAILS CLOSED (nothing recorded, nothing deleted).
// ---------------------------------------------------------------------------

export function resolveOfficeReplyId(rows, { threadId, body, senderType = "admin" }) {
  const list = Array.isArray(rows) ? rows : [];
  const matches = list.filter(
    (r) => r && r.id && r.thread_id === threadId && r.sender_type === senderType && r.body === body,
  );
  if (matches.length !== 1 || !matches[0].id) {
    throw new Error(
      `office reply id not uniquely identified for thread ${threadId} (got ${matches.length} match(es)) - FAILING CLOSED; no id recorded, cleanup cannot target it`,
    );
  }
  return matches[0].id;
}